from statistics import NormalDist


def interval_score(lo, hi, truth, alpha=0.1):
    """Width plus 2/alpha times any miss distance."""
    w = 2 / alpha
    return (hi - lo) + w * max(0, lo - truth) + w * max(0, truth - hi)


def hit_rate(ranges, truths):
    """Share of (lo, hi) ranges that hold their truth."""
    hits = sum(lo <= t <= hi for (lo, hi), t in zip(ranges, truths))
    return hits / len(truths)


def normal_range(mean, sd, level=0.9):
    """(lo, hi) holding level of a normal belief,
    rounded to 2 places."""
    z = NormalDist().inv_cdf(0.5 + level / 2)
    return (round(mean - z * sd, 2), round(mean + z * sd, 2))
